"""Camera-guided stove manipulation. Uses only the standard robot API.
Commands are logged beside this script; observations retain RGB, depth and calibration.
"""
from rcb_client import Robot
import numpy as np
import json,sys
from pathlib import Path
from PIL import Image,ImageDraw
ROOT=Path('/app/output')
r=Robot()
obs=None
idx=0

def save(o,label):
 global obs,idx
 obs=o;idx+=1
 path=ROOT/f'{idx:03d}_{label}'
 o.save(str(path))
 (ROOT/'latest.json').write_text(json.dumps(o.meta))
 ims=list(o.last.items()); out=Image.new('RGB',(640,520)); draw=ImageDraw.Draw(out)
 for i,(name,im) in enumerate(ims):
  x=i%2*320;y=i//2*260;out.paste(Image.fromarray(im),(x,y));draw.text((x,y+240),name,fill='white')
 out.save(ROOT/'latest.png')
 for name,im in ims: Image.fromarray(im).save(ROOT/(name+'.png'))
 p=o.meta['proprio']; v=dict(zip(p['layout'],p['now']))
 print(json.dumps({'saved':str(path),'steps':o.meta['control_steps'],'remaining':o.meta['time_left_s'],'eef':[v[k] for k in ['eef_right_x','eef_right_y','eef_right_z']],'joints':p['now'][:13]}),flush=True)

def act(a,n=1,label='motion'):
 A=np.tile(np.array(a,float),(n,1)) if np.asarray(a).ndim==1 else np.array(a,float)
 with open(ROOT/'actions.jsonl','a') as f:f.write(json.dumps({'actions':A.tolist(),'label':label})+'\n')
 save(r.submit('ee_delta',A,include_depth=True,video='none',note=label),label)

def cmd(d):
 if d['op']=='obs':save(r.get_obs(include_depth=True,video='none'),'observe')
 elif d['op']=='act':act(d['a'],d.get('n',1),d.get('label','motion'))
 elif d['op']=='exec':exec(d['code'],globals())

if __name__=='__main__':
 for line in sys.stdin:
  try:cmd(json.loads(line))
  except Exception as e:print(type(e).__name__,str(e),flush=True)
